ControlMaster=no',\n      '-o', 'ControlPath=none',\n      // 不压低日志级别：「Connection closed」「timed out」这类关键原因是 INFO 级，压到 ERROR 就只剩退出码 255\n    ]\n    let askDir = null\n    const childEnv = { ...env }\n    // 要交给 ssh 的口令：密码登录的密码，或加密私钥的口令\n    const secret = auth === 'password' ? password : auth === 'key' ? passphrase : ''\n    if (secret || auth === 'key') askDir = await mkdtemp(join(tmpdir(), 'dsh-vps-ssh-'))\n    if (secret) {\n      const helper = join(askDir, platform === 'win32' ? 'askpass.cmd' : 'askpass.sh')\n      if (platform === 'win32') {\n        await writeFile(helper, `@set ELECTRON_RUN_AS_NODE=1\\r\\n@\"${process.execPath}\" -e \"process.stdout.write(process.env.DSH_VPS_PW+'\\\\n')\"\\r\\n`)\n      } else {\n        await writeFile(helper, '#!/bin/sh\\nprintf \\'%s\\\\n\\' \"$DSH_VPS_PW\"\\n', { mode: 0o700 })\n      }\n      args.push('-o', 'NumberOfPasswordPrompts=1')\n      Object.assign(childEnv, { SSH_ASKPASS: helper, SSH_ASKPASS_REQUIRE: 'force', DISPLAY: env.DISPLAY || ':0', DSH_VPS_PW: secret })\n    } else {\n      args.push('-o', 'BatchMode=yes')\n    }\n    if (auth === 'password') {\n      args.push('-o', 'PreferredAuthentications=keyboard-interactive,password', '-o', 'PubkeyAuthentication=no')\n    } else if (auth === 'key') {\n      const keyFile = join(askDir, 'id_key')\n      await writeFile(keyFile, privateKey, { mode: 0o600 })\n      args.push('-i', keyFile, '-o', 'IdentitiesOnly=yes', '-o', 'PreferredAuthentications=publickey')\n    } else {\n      // 本机密钥：本插件专用的那把 + ~/.ssh 里的默认私钥（ssh-agent 里的也照样会试）\n      for (const f of [localKeyPath(env), ...defaultIdentities()]) if (existsSync(f)) args.push('-i', f)\n      args.push('-o', 'PreferredAuthentications=publickey')\n    }\n    args.push('--', target, 'sh -s')\n\n    let child\n    try {\n      // windowsHide：Windows 上的 DSH（含桌面版）启动 ssh 时不弹控制台窗口\n      child = spawnImpl('ssh', args, { env: childEnv, stdio: ['pipe', 'pipe', 'pipe'], windowsHide: true })\n    } catch (error) {\n      if (askDir) rm(askDir, { recursive: true, force: true }).catch(() => {})\n      current.state = 'failed'\n      current.error = /ENOENT/.test(String(error.message)) ? noSshClientHint(platform) : `无法启动 ssh：${error.message}`\n      current.endedAt = now()\n      return { job: snapshot().job }\n    }\n    current.child = child\n    let stderr = ''\n    let buf = ''\n    // 按完整字符解码：汉字可能被切在两个数据块之间\n    const outDec = new StringDecoder('utf8')\n    const errDec = new StringDecoder('utf8')\n    const push = (line) => {\n      const clean = strip(line)\n      if (clean === 'DSHVPS_STARTED') {\n        current.phase = 'installing'\n        return\n      }\n      current.lines.push(clean)\n      if (current.lines.length > MAX_LINES * 2) current.lines.splice(0, current.lines.length - MAX_LINES)\n      if (action === 'install' && !current.setupUrl) current.setupUrl = findSetupUrl(clean)\n      if (action === 'uninstall' && !current.backupPath) current.backupPath = findBackupPath(clean)\n    }\n    child.stdout.on('data', (d) => {\n      buf += outDec.write(d)\n      const parts = buf.split('\\n')\n      buf = parts.pop()\n      for (const p of parts) push(p)\n    })\n    child.stderr.on('data', (d) => {\n      stderr = (stderr + errDec.write(d)).slice(-4000)\n    })\n    const finish = (code) => {\n      if (current.endedAt) return\n      clearTimeout(current.timer)\n      if (buf) push(buf)\n      if (askDir) rm(askDir, { recursive: true, force: true }).catch(() => {})\n      current.endedAt = now()\n      const exitLine = current.lines.find((l) => /^DSHVPS_EXIT=\\d+/.test(l))\n      current.lines = current.lines.filter((l) => !/^DSHVPS_(EXIT|ERR)=/.test(l))\n      const remoteExit = exitLine ? Number(exitLine.split('=')[1]) : null\n      if (remoteExit === 0) {\n        current.state = 'success'\n      } else if (remoteExit !== null) {\n        current.state = 'failed'\n        current.error = `${verb}脚本执行失败（退出码 ${remoteExit}），详见下方日志；服务器上的完整日志：${remoteLog}`\n      } else if (current.phase === 'installing') {\n        current.state = 'failed'\n        current.error = action === 'uninstall'\n          ? `与服务器的连接中断了，但卸载仍在服务器上继续运行。稍后 SSH 登录执行 sudo tail -n 50 ${remoteLog} 查看结果`\n          : `与服务器的连接中断了，但安装仍在服务器上继续运行。稍后 SSH 登录执行 sudo tail -n 50 ${remoteLog} 查看结果，或执行 sudo dsh-vps setup-url 取设置链接`\n      } else {\n        current.state = 'failed'\n        current.error = classifyFailure(stderr, code, auth, platform)\n      }\n    }\n    child.on('error', (error) => {\n      stderr += `\\n${error.message}`\n      finish(255)\n    })\n    child.on('close', (code) => finish(code))\n    current.timer = setTimeout(() => {\n      try {\n        child.kill('SIGTERM')\n      } catch {\n        // 已退出\n      }\n    }, JOB_TIMEOUT_MS)\n    child.stdin.end(remoteScript({ action, domain, mirror, keepData, purgeCaddy }))\n    return { job: snapshot().job }\n  }\n\n  function dispose() {\n    if (job?.child && !job.endedAt) {\n      try {\n        job.child.kill('SIGTERM')\n      } catch {\n        // 已退出\n      }\n    }\n  }\n\n  return { start, snapshot, dispose }\n}\n"
    },
    {
      "path": "install.sh",
      "content": "#!/usr/bin/env bash\n# dsh-vps 一键安装脚本（M2）\n#\n# 用法：\n#   curl -fsSL https://raw.githubusercontent.com/AIcivilization/dsh-vps/main/install.sh \\\n#     | sudo bash -s -- --domain dsh.example.com\n#   # 或在仓库克隆目录内：\n#   sudo bash install.sh --domain dsh.example.com [--mirror cn]\n#\n# 目标 OS：Ubuntu 22.04+ / Debian 12+（裸机，无 Docker）\n# 设计依据：dsh-vps-architecture-design.md §4.1 / §4.3 / §4.4 / §5 / §10\n#\n# 说明：仓库已公开，curl 管道模式可直接拉取 gate 代码；若在克隆目录内运行则优先用本地文件。\n\nset -euo pipefail\n\n## region: 常量与参数\n\n# 默认装官方最新版：npm latest 与 next 渠道里版本号更高、且发布满 12 小时的那个——与网关页面\n# 「有新版本」提示、dsh-vps upgrade --latest 同一规则（alpha 等内部渠道不取）。\n# 以前钉死一个版本，新装的机器一上来就是旧版，还得再点一次升级。\n# 最新版装不上、或装好后起不来，自动退回下面这个验证过的版本（其依赖树按时间点冻结，必定能装）。\n# 显式指定：--dsh <版本> 或 --dsh verified；环境变量 DSH_VERSION 同效。\nDSH_VERIFIED=\"0.1.7-rc.1\" # 已验证版本（versions.json 的 latest_verified）\nDSH_VERSION=\"${DSH_VERSION:-}\"\nUPGRADE_COOLDOWN_HOURS=12\nLAST_HEALTH=\"\"\n# 只钉顶层包版本是不够的：DSH 各子包的依赖是 ^0.1.5-rc.2 这类浮动范围，上游一发新的\n# 预发布波次，解析结果就整体漂上去。2026-09-22 上游发了 0.1.5-rc.3 波次，但漏发了\n# dsh-client-ui-sidebar-documentpreview，于是 ETARGET 装不上。用 --before 把解析冻结在\n# 验证通过的那个时间点之前，装到的就是验证过的那棵树。升级 DSH_VERSION 时同步推后这个值。\n# 注意：同一天 03:46 上游还先发了一批 cordis 系列（cordis 4.0.3 / cordis-plugin-hmr 1.0.18 等），\n# 与 rc.2 不兼容——web profile 启动即报 \"user patch-layer watching requires the Cordis HMR service\"。\n# 冻结点必须早于这一批，所以是 03:40 而不是 05:00。\n# 之后升到 0.1.7-rc.1（npm next 渠道），冻结点 2026-09-24T08:20Z——该时刻解析出的依赖树已逐包比对、实测通过。\n# 冻结只用于已验证版本；官方最新版按当下解析（与页面一键升级一致）。设为 none 可关闭冻结。\nDSH_RESOLVE_BEFORE=\"${DSH_RESOLVE_BEFORE:-2026-09-24T08:20:00Z}\"\nINSTALL_ROOT=\"/opt/dsh-vps\"\nDSH_USER=\"dsh\"\nDSH_HOME_DIR=\"/home/dsh/.dsh\"\nGATE_PORT=3100\nDSH_PORT=3080\n# gate/unit/caddy 模板来源：优先脚本同目录（仓库克隆），否则从 raw 地址下载\nRAW_BASE=\"${DSHVPS_RAW_BASE:-https://raw.githubusercontent.com/AIcivilization/dsh-vps/main}\"\n\nDOMAIN=\"\"\nMIRROR=\"\"\n\nlog()  { printf '\\033[1;32m[install]\\033[0m %s\\n' \"$*\"; }\nwarn() { printf '\\033[1;33m[install]\\033[0m %s\\n' \"$*\" >&2; }\ndie()  { printf '\\033[1;31m[install]\\033[0m %s\\n' \"$*\" >&2; exit 1; }\n\nusage() {\n\tcat <<'EOF'\ndsh-vps 安装脚本\n用法: sudo bash install.sh [--domain <域名>] [--mirror cn] [--dsh <版本>|verified]\n  --domain <域名>   访问域名（需已解析到本机）。不传则以公网 IP + 自签证书过渡\n  --mirror cn       国内镜像：Node 走 npmmirror 二进制，DSH 走 npmmirror registry\n  --dsh <版本>      指定 DSH 版本；verified 表示 dsh-vps 验证过的版本。默认官方最新版\nEOF\n}\n\nwhile [[ $# -gt 0 ]]; do\n\tcase \"$1\" in\n\t--domain) DOMAIN=\"${2:?--domain 需要一个值}\"; shift 2 ;;\n\t--mirror) MIRROR=\"${2:?--mirror 需要一个值}\"; shift 2 ;;\n\t--dsh) DSH_VERSION=\"${2:?--dsh 需要一个值}\"; shift 2 ;;\n\t-h | --help) usage; exit 0 ;;\n\t*) die \"未知参数: $1（--help 查看用法）\" ;;\n\tesac\ndone\n\n[[ \"$MIRROR\" == \"\" || \"$MIRROR\" == \"cn\" ]] || die \"--mirror 目前仅支持 cn\"\n[[ \"$DSH_VERSION\" == \"verified\" ]] && DSH_VERSION=\"$DSH_VERIFIED\"\n[[ -z \"$DSH_VERSION\" || \"$DSH_VERSION\" =~ ^[0-9]+\\.[0-9]+\\.[0-9]+(-[0-9A-Za-z.-]+)?$ ]] || die \"--dsh 版本号格式不对: $DSH_VERSION\"\nDSH_PICKED_BY=\"指定\"\nif [[ -n \"$DOMAIN\" ]]; then\n\t[[ \"$DOMAIN\" =~ ^[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?(\\.[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?)+$ ]] \\\n\t\t|| die \"域名格式不合法: $DOMAIN\"\nfi\n\nSCRIPT_DIR=\"\"\nif [[ -n \"${BASH_SOURCE[0]:-}\" && -f \"${BASH_SOURCE[0]}\" ]]; then\n\tSCRIPT_DIR=$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\nfi\n\n# 取仓库文件：本地克隆优先，否则走 RAW_BASE\nfetch_file() { # $1=仓库内相对路径 $2=目标路径\n\tlocal rel=\"$1\" dst=\"$2\"\n\tif [[ -n \"$SCRIPT_DIR\" && -f \"$SCRIPT_DIR/$rel\" ]]; then\n\t\tinstall -m 644 \"$SCRIPT_DIR/$rel\" \"$dst\"\n\telse\n\t\tcurl -fsSL \"$RAW_BASE/$rel\" -o \"$dst\" \\\n\t\t\t|| die \"下载 $rel 失败（仓库未发布时请在克隆目录内运行本脚本）\"\n\tfi\n}\n\nexport DEBIAN_FRONTEND=noninteractive\ntrap 'warn \"安装失败（行 ${LINENO}），可用 journalctl -u dsh-gate -n 50 排查服务问题\"' ERR\n\n## endregion\n\n## region: 步骤 1：前置检查\n\nREINSTALL=0\n\nstep1_prechecks() {\n\tlog \"步骤 1/9：前置检查\"\n\t[[ $EUID -eq 0 ]] || die \"请用 root 运行（sudo bash install.sh ...）\"\n\tcommand -v curl >/dev/null 2>&1 || { apt-get update -y >/dev/null; apt-get install -y curl ca-certificates >/dev/null; }\n\n\t# OS 检查\n\t. /etc/os-release\n\tlocal ok=0\n\tcase \"${ID:-}\" in\n\tubuntu) awk -v v=\"${VERSION_ID:-0}\" 'BEGIN{exit !(v>=22.04)}' && ok=1 ;;\n\tdebian) awk -v v=\"${VERSION_ID:-0}\" 'BEGIN{exit !(v>=12)}' && ok=1 ;;\n\tesac\n\t[[ $ok -eq 1 ]] || die \"不支持的发行版: ${ID:-unknown} ${VERSION_ID:-}（目标：Ubuntu 22.04+ / Debian 12+）\"\n\n\t# glibc 检查（Ubuntu 22.04=2.35 / Debian 12=2.36，正常必然通过，仅告警）\n\tlocal glibc\n\tglibc=$(ldd --version 2>/dev/null | head -1 | grep -oE '[0-9]+\\.[0-9]+$' || echo 0)\n\tawk -v v=\"$glibc\" 'BEGIN{exit !(v>=2.28)}' || warn \"glibc $glibc < 2.28，DSH 可能无法运行\"\n\n\t# 内存检查（< 1.5G 仅告警）\n\tlocal mem_kb\n\tmem_kb=$(awk '/MemTotal/{print $2}' /proc/meminfo)\n\t[[ \"$mem_kb\" -lt 1572864 ]] && warn \"内存 $((mem_kb / 1024))MB 低于建议的 1.5GB，体验可能不稳定\"\n\n\t# 幂等判定：已有安装则进入修复/更新模式（不碰 state/ 内的凭据与 setup.lock）\n\t[[ -f \"$INSTALL_ROOT/state/config.json\" ]] && REINSTALL=1\n\n\t# 端口检查（重装时本机服务已占用这些端口，跳过）\n\tif [[ $REINSTALL -eq 0 ]]; then\n\t\tlocal p\n\t\tfor p in 80 443 \"$DSH_PORT\" \"$GATE_PORT\"; do\n\t\t\tif ss -ltn 2>/dev/null | awk '{print $4}' | grep -qE \"[:.]${p}$\"; then\n\t\t\t\tdie \"端口 $p 已被占用，请先释放（重装场景请保留 $INSTALL_ROOT 后重跑）\"\n\t\t\tfi\n\t\tdone\n\telse\n\t\tlog \"检测到已有安装（${INSTALL_ROOT}），进入修复/更新模式（保留 state/）\"\n\tfi\n}\n\n## endregion\n\n## region: 步骤 2：Node.js 22\n\ninstall_node_nodesource() {\n\tcurl -fsSL https://deb.nodesource.com/setup_22.x -o /tmp/nodesource_setup.sh\n\tbash /tmp/nodesource_setup.sh >/dev/null\n\tapt-get install -y nodejs >/dev/null\n}\n\ninstall_node_cn() {\n\t# npmmirror 二进制镜像：取 latest-v22.x 目录中最新的 linux-x64 包并校验 sha256\n\tlocal list pkg\n\tlist=$(curl -fsSL --max-time 30 \"https://registry.npmmirror.com/-/binary/node/latest-v22.x/\")\n\tpkg=$(printf '%s' \"$list\" | grep -o 'node-v22[0-9.]*-linux-x64\\.tar\\.xz' | sort -Vu | tail -1)\n\t[[ -n \"$pkg\" ]] || die \"无法从 npmmirror 获取 Node 22 版本号\"\n\tlog \"下载 Node.js: ${pkg}（npmmirror）\"\n\tcurl -fsSL --retry 2 -o \"/tmp/$pkg\" \"https://registry.npmmirror.com/-/binary/node/latest-v22.x/$pkg\"\n\t(cd /tmp && curl -fsSL \"https://registry.npmmirror.com/-/binary/node/latest-v22.x/SHASUMS256.txt\" \\\n\t\t| grep \"${pkg}\\$\" | sha256sum -c - >/dev/null) || die \"Node 包 sha256 校验失败\"\n\ttar -xJf \"/tmp/$pkg\" -C /usr/local --strip-components=1\n\trm -f \"/tmp/$pkg\"\n\thash -r\n}\n\nstep2_node() {\n\tlog \"步骤 2/9：Node.js 22 + pnpm\"\n\tlocal major\n\tmajor=$(node --version 2>/dev/null | sed -n 's/^v\\{0,1\\}\\([0-9]\\{1,\\}\\).*/\\1/p' || true)\n\tif [[ \"${major:-0}\" -ge 22 ]]; then\n\t\tlog \"已安装 Node $(node --version)，跳过\"\n\telse\n\t\tapt-get update -y >/dev/null\n\t\tif [[ \"$MIRROR\" == \"cn\" ]]; then install_node_cn; else install_node_nodesource; fi\n\t\tmajor=$(node --version | sed -n 's/^v\\{0,1\\}\\([0-9]\\{1,\\}\\).*/\\1/p')\n\t\t[[ \"${major:-0}\" -ge 22 ]] || die \"Node.js 22 安装失败\"\n\t\tlog \"Node $(node --version) 安装完成\"\n\tfi\n\n\t# pnpm：`dsh plugin` 管理插件依赖的包管理器（/setup 向导可选安装插件需要）\n\tif ! command -v pnpm >/dev/null 2>&1; then\n\t\tlog \"安装 pnpm（插件管理需要）\"\n\t\tif [[ \"$MIRROR\" == \"cn\" ]]; then\n\t\t\tnpm install -g pnpm --registry=https://registry.npmmirror.com >/dev/null 2>&1 \\\n\t\t\t\t|| npm install -g pnpm >/dev/null 2>&1 || true\n\t\telse\n\t\t\tnpm install -g pnpm >/dev/null 2>&1 || true\n\t\tfi\n\tfi\n\tcommand -v pnpm >/dev/null 2>&1 || warn \"pnpm 未安装，插件安装功能不可用（可稍后 npm i -g pnpm）\"\n}\n\n## endregion\n\n## region: 步骤 3：DSH 版本化安装\n\n# 官方最新版：latest / next 中版本号更高、发布满冷静期的；查不到输出空\nnewest_dsh() {\n\tlocal reg=()\n\t[[ \"$MIRROR\" == \"cn\" ]] && reg+=(--registry=https://registry.npmmirror.com)\n\tnpm view @deepseek-ai/dsh dist-tags time --json ${reg[@]+\"${reg[@]}\"} 2>/dev/null | COOLDOWN_H=\"$UPGRADE_COOLDOWN_HOURS\" node -e '\nconst doc = JSON.parse(require(\"fs\").readFileSync(0, \"utf8\"));\nconst t = doc[\"dist-tags\"] || {};\nconst times = doc.time || {};\nconst cooldown = Number(process.env.COOLDOWN_H || 12) * 3600000;\nconst parse = (v) => { const [c, p] = v.split(\"-\", 2); return { c: c.split(\".\").map(Number), p: p === undefined ? null : p.split(\".\") }; };\nconst cmp = (a, b) => {\n\tconst x = parse(a), y = parse(b);\n\tfor (let i = 0; i < 3; i++) if (x.c[i] !== y.c[i]) return x.c[i] - y.c[i];\n\tif (x.p === null || y.p === null) return (x.p === null) - (y.p === null);\n\tfor (let i = 0; i < Math.max(x.p.length, y.p.length); i++) {\n\t\tconst p = x.p[i], q = y.p[i];\n\t\tif (p === undefined || q === undefined) return p === undefined ? -1 : 1;\n\t\tconst pn = /^\\d+$/.test(p), qn = /^\\d+$/.test(q);\n\t\tif (pn && qn && +p !== +q) return +p - +q;\n\t\tif (pn !== qn) return pn ? -1 : 1;\n\t\tif (p !== q) return p < q ? -1 : 1;\n\t}\n\treturn 0;\n};\nconst c = [t.latest, t.next].filter((v) => typeof v === \"string\" && /^\\d+\\.\\d+\\.\\d+(-[0-9A-Za-z.-]+)?$/.test(v))\n\t.filter((v) => { const at = Date.parse(times[v] || \"\"); return Number.isFinite(at) && Date.now() - at >= cooldown; });\nif (c.length) console.log(c.sort(cmp).pop());\n' 2>/dev/null || true\n}\n\n# 把 DSH $1 装进 $INSTALL_ROOT/dsh/$1；已验证版本按时间点冻结解析。成功返回 0\ninstall_dsh_version() {\n\tlocal ver=\"$1\"\n\tlocal prefix=\"$INSTALL_ROOT/dsh/$ver\"\n\tlocal bin=\"$prefix/node_modules/@deepseek-ai/dsh/lib/bin.js\"\n\tif [[ -f \"$bin\" ]]; then\n\t\tlog \"DSH $ver 已安装，跳过\"\n\t\treturn 0\n\tfi\n\tmkdir -p \"$prefix\"\n\t# 数组恒不为空：bash 3.2 在 set -u 下展开空数组会报 unbound variable\n\tlocal args=(--no-audit --no-fund --loglevel=error)\n\t[[ \"$MIRROR\" == \"cn\" ]] && args+=(--registry=https://registry.npmmirror.com)\n\tlocal frozen=0\n\t[[ \"$ver\" == \"$DSH_VERIFIED\" && \"$DSH_RESOLVE_BEFORE\" != \"none\" ]] && frozen=1\n\tlocal a1=(\"${args[@]}\")\n\t[[ $frozen -eq 1 ]] && a1+=(--before=\"$DSH_RESOLVE_BEFORE\")\n\tif ! npm install --prefix \"$prefix\" \"${a1[@]}\" \"@deepseek-ai/dsh@$ver\"; then\n\t\t# 冻结解析本身失败（例如镜像源不带发布时间戳）时退化为不冻结\n\t\tif [[ $frozen -eq 1 ]]; then\n\t\t\twarn \"按时间点冻结解析失败，改为不冻结重试\"\n\t\t\tnpm install --prefix \"$prefix\" \"${args[@]}\" \"@deepseek-ai/dsh@$ver\" || true\n\t\tfi\n\tfi\n\tif [[ ! -f \"$bin\" ]]; then\n\t\trm -rf \"$prefix\"\n\t\treturn 1\n\tfi\n\treturn 0\n}\n\nstep3_dsh() {\n\tif [[ -z \"$DSH_VERSION\" ]]; then\n\t\tDSH_VERSION=$(newest_dsh)\n\t\tif [[ -n \"$DSH_VERSION\" ]]; then\n\t\t\tDSH_PICKED_BY=\"官方最新版\"\n\t\telse\n\t\t\twarn \"查不到 DSH 官方最新版本，改装已验证版本 $DSH_VERIFIED\"\n\t\t\tDSH_VERSION=\"$DSH_VERIFIED\"\n\t\tfi\n\tfi\n\t[[ \"$DSH_VERSION\" == \"$DSH_VERIFIED\" && \"$DSH_PICKED_BY\" != \"官方最新版\" ]] && DSH_PICKED_BY=\"已验证版本\"\n\tlog \"步骤 3/9：DeepSeek Harness ${DSH_VERSION}（${DSH_PICKED_BY}，版本化安装）\"\n\tif ! install_dsh_version \"$DSH_VERSION\"; then\n\t\t[[ \"$DSH_VERSION\" != \"$DSH_VERIFIED\" ]] || die \"DSH $DSH_VERSION 安装失败\"\n\t\twarn \"DSH $DSH_VERSION 安装失败，改装已验证版本 $DSH_VERIFIED\"\n\t\tDSH_VERSION=\"$DSH_VERIFIED\"\n\t\tDSH_PICKED_BY=\"已验证版本（最新版安装失败后退回）\"\n\t\tinstall_dsh_version \"$DSH_VERSION\" || die \"DSH $DSH_VERSION 安装失败\"\n\tfi\n\tln -sfn \"$DSH_VERSION\" \"$INSTALL_ROOT/dsh/current\"\n}\n\n## endregion\n\n## region: 步骤 4：运行身份\n\nstep4_user() {\n\tlog \"步骤 4/9：系统用户 $DSH_USER\"\n\tif ! id \"$DSH_USER\" >/dev/null 2>&1; then\n\t\tuseradd --system --shell /usr/sbin/nologin --home-dir /home/dsh --create-home \"$DSH_USER\"\n\tfi\n\tmkdir -p \"$DSH_HOME_DIR\"\n\tchown -R \"$DSH_USER\" \"$DSH_HOME_DIR\"\n\tchmod 700 \"$DSH_HOME_DIR\"\n}\n\n## endregion\n\n## region: 步骤 5：dsh-gate 代码\n\n# 一次性启动令牌：初始向导在安装结束到用户首次打开浏览器之间是全网可达的，\n# 谁先提交谁就是管理员。令牌写进 state/setup.token，向导提交成功后由 gate 删除。\ngenerate_setup_token() {\n\tSETUP_TOKEN=\"\"\n\t[[ -f \"$INSTALL_ROOT/state/setup.lock\" ]] && return 0\n\tlocal tok\n\ttok=$(head -c 32 /dev/urandom | base64 | tr -dc 'A-Za-z0-9' | head -c 32)\n\tif [[ ${#tok} -lt 24 ]]; then\n\t\twarn \"启动令牌生成失败，向导将不校验令牌\"\n\t\treturn 0\n\tfi\n\tprintf '%s' \"$tok\" >\"$INSTALL_ROOT/state/setup.token\"\n\tchown \"$DSH_USER\" \"$INSTALL_ROOT/state/setup.token\" 2>/dev/null || true\n\tchmod 600 \"$INSTALL_ROOT/state/setup.token\"\n\tSETUP_TOKEN=\"$tok\"\n\tlog \"已生成一次性启动令牌\"\n}\n\nstep5_gate() {\n\tlog \"步骤 5/9：dsh-gate\"\n\tmkdir -p \"$INSTALL_ROOT/gate\" \"$INSTALL_ROOT/bin\"\n\tfetch_file gate/server.js \"$INSTALL_ROOT/gate/server.js\"\n\tnode --check \"$INSTALL_ROOT/gate/server.js\" || die \"gate/server.js 语法检查失败\"\n\tfetch_file gate/site-block.js \"$INSTALL_ROOT/gate/site-block.js\"\n\tnode --check \"$INSTALL_ROOT/gate/site-block.js\" || die \"gate/site-block.js 语法检查失败\"\n\tfetch_file bin/dsh-vps \"$INSTALL_ROOT/bin/dsh-vps\"\n\tchmod 755 \"$INSTALL_ROOT/bin/dsh-vps\"\n\tbash -n \"$INSTALL_ROOT/bin/dsh-vps\" || die \"bin/dsh-vps 语法检查失败\"\n\tln -sfn \"$INSTALL_ROOT/bin/dsh-vps\" /usr/local/bin/dsh-vps\n\t# 公网域名下浏览器判定 isLoopback=false，设置页会报\"设置在此浏览器中不可用\"。\n\t# 直接写前端静态文件解除该判定（DSH 每次响应都重读该文件，无需重启）。\n\tdsh-vps ownshost on || warn \"ownsHost 补丁未生效，稍后可手动运行: sudo dsh-vps ownshost on\"\n\tmkdir -p \"$INSTALL_ROOT/state\"\n\tchmod 700 \"$INSTALL_ROOT/state\"\n\tgenerate_setup_token\n}\n\n## endregion\n\n## region: 步骤 6：Caddy\n\nstep6_caddy() {\n\tlog \"步骤 6/9：Caddy\"\n\tif ! command -v caddy >/dev/null 2>&1; then\n\t\tapt-get install -y debian-keyring debian-archive-keyring apt-transport-https gpg >/dev/null\n\t\tcurl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/gpg.key' \\\n\t\t\t| gpg --dearmor -o /usr/share/keyrings/caddy-stable-archive-keyring.gpg\n\t\tcurl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/debian.deb.txt' \\\n\t\t\t>/etc/apt/sources.list.d/caddy-stable.list\n\t\tapt-get update -y >/dev/null\n\t\tapt-get install -y caddy >/dev/null\n\tfi\n\n\t# 主 Caddyfile（静态，import 站点文件）+ 站点文件（向导改域名时由 gate 重写）\n\tfetch_file caddy/Caddyfile.template /tmp/Caddyfile.dshvps\n\tif [[ -f /etc/caddy/Caddyfile ]] && ! cmp -s /etc/caddy/Caddyfile /tmp/Caddyfile.dshvps; then\n\t\tcp /etc/caddy/Caddyfile \"/etc/caddy/Caddyfile.bak.$(date +%s)\"\n\tfi\n\t# 同一台机器上别的产品（比如 vpssh）共用这个 Caddy，会在主 Caddyfile 末尾加自己的 import 行：\n\t# 重写时原样保留，不然重装一次 dsh-vps，别的网站就从 Caddy 里消失了\n\tlocal keep=\"\"\n\tif [[ -f /etc/caddy/Caddyfile ]]; then\n\t\tkeep=$(grep -E '^(import /etc/caddy/|# vpssh：)' /etc/caddy/Caddyfile | grep -vxF \"import /etc/caddy/dsh-site.conf\" || true)\n\tfi\n\tinstall -m 644 /tmp/Caddyfile.dshvps /etc/caddy/Caddyfile\n\tif [[ -n \"$keep\" ]]; then\n\t\tprintf '%s\\n' \"$keep\" >>/etc/caddy/Caddyfile\n\t\tlog \"保留了同机其他网站在 Caddyfile 里的 import 行\"\n\tfi\n\n\t# 站点块：有域名写域名块（自动 HTTPS），无则按公网 IP 写站点、Caddy 内置 CA 自签过渡\n\t# 属主 dsh（向导重写）、组 caddy（Caddy 读取）、640\n\t# 站点块由 gate/site-block.js 生成：install.sh 写初始块、gate 改域名、dsh-vps vpn\n\t# 切换访问策略，三处共用同一份模板。重装时若 state/vpn.env 还开着隧道模式，\n\t# 这里会直接沿用「仅隧道可访问」，不会把已经关上的门重新敞开。\n\tlocal site=\"$TRUSTED_HOST\"\n\tnode \"$INSTALL_ROOT/gate/site-block.js\" \"$site\" \"$INSTALL_ROOT\" \"$GATE_PORT\" \\\n\t\t>/etc/caddy/dsh-site.conf || die \"生成站点块失败\"\n\tchown \"$DSH_USER\":caddy /etc/caddy/dsh-site.conf\n\tchmod 640 /etc/caddy/dsh-site.conf\n\n\tsystemctl enable --now caddy >/dev/null 2>&1 || true\n\tsystemctl reload caddy >/dev/null 2>&1 || systemctl restart caddy\n\tlog \"Caddyfile 已生效（站点：${site}）\"\n}\n\n## endregion\n\n## region: 步骤 7：systemd + gate.env + config.json\n\ndetect_public_ip() {\n\tlocal ip url\n\tfor url in https://api.ipify.org https://ifconfig.me https://icanhazip.com; do\n\t\tip=$(curl -4 -fsSL --max-time 5 \"$url\" 2>/dev/null | tr -d '[:space:]') || continue\n\t\tif [[ \"$ip\" =~ ^[0-9]+\\.[0-9]+\\.[0-9]+\\.[0-9]+$ ]]; then\n\t\t\tprintf '%s' \"$ip\"\n\t\t\treturn 0\n\t\tfi\n\tdone\n\tip=$(hostname -I 2>/dev/null | awk '{print $1}')\n\t[[ -n \"$ip\" ]] || die \"无法探测公网 IP，请显式传 --domain\"\n\tprintf '%s' \"$ip\"\n}\n\n# 访问地址（= DSH --trusted-host = Caddy 站点地址）必须在写站点块之前确定：\n# 域名优先；重装且未传 --domain 时沿用已有配置（含向导改过的域名）；最后回退公网 IP。\nTRUSTED_HOST=\"\"\nCFG_DOMAIN=\"\"\nPUBLIC_IP=\"\"\nresolve_trusted_host() {\n\tTRUSTED_HOST=\"${DOMAIN:-}\"\n\tlocal existing_domain=\"\"\n\tif [[ -z \"$TRUSTED_HOST\" && $REINSTALL -eq 1 ]]; then\n\t\tif [[ -f \"$INSTALL_ROOT/state/gate.env\" ]]; then\n\t\t\tTRUSTED_HOST=$(sed -n 's/^DSH_TRUSTED_HOST=//p' \"$INSTALL_ROOT/state/gate.env\" | tail -1)\n\t\tfi\n\t\tif [[ -f \"$INSTALL_ROOT/state/config.json\" ]]; then\n\t\t\texisting_domain=$(sed -n 's/.*\"domain\": *\"\\([^\"]*\\)\".*/\\1/p' \"$INSTALL_ROOT/state/config.json\" | tail -1)\n\t\tfi\n\tfi\n\tif [[ -z \"$TRUSTED_HOST\" ]]; then\n\t\tTRUSTED_HOST=$(detect_public_ip)\n\tfi\n\tCFG_DOMAIN=\"${DOMAIN:-$existing_domain}\"\n\t# 记下这台机器的公网 IP：设置页里改域名时拿它核对域名解析，改回 IP 访问时也用它\n\tif [[ \"$TRUSTED_HOST\" =~ ^[0-9]+\\.[0-9]+\\.[0-9]+\\.[0-9]+$ ]]; then\n\t\tPUBLIC_IP=\"$TRUSTED_HOST\"\n\telse\n\t\tPUBLIC_IP=$(sed -n 's/.*\"publicIp\": *\"\\([^\"]*\\)\".*/\\1/p' \"$INSTALL_ROOT/state/config.json\" 2>/dev/null | head -1 || true)\n\t\t[[ -n \"$PUBLIC_IP\" ]] || PUBLIC_IP=$(detect_public_ip 2>/dev/null || true)\n\tfi\n}\n\nstep7_systemd() {\n\tlog \"步骤 7/9：systemd 服务\"\n\tmkdir -p \"$INSTALL_ROOT/state\" \"$INSTALL_ROOT/backups\"\n\n\tlocal trusted=\"$TRUSTED_HOST\"\n\tlocal cfg_domain=\"$CFG_DOMAIN\"\n\n\t# gate.env：集中管理运行环境变量（0600 属主 dsh，M3 向导改域名后重写并 restart 即可）\n\tcat >\"$INSTALL_ROOT/state/gate.env\" <<EOF\nGATE_HOME=$INSTALL_ROOT\nDSH_BIN=$INSTALL_ROOT/dsh/current/node_modules/@deepseek-ai/dsh/lib/bin.js\nDSH_HOME=$DSH_HOME_DIR\nDSH_TRUSTED_HOST=$trusted\nEOF\n\tchmod 600 \"$INSTALL_ROOT/state/gate.env\"\n\tchown \"$DSH_USER\" \"$INSTALL_ROOT/state/gate.env\"\n\n\t# config.json：安装元数据\n\tcat >\"$INSTALL_ROOT/state/config.json\" <<EOF\n{\n  \"dshVersion\": \"$DSH_VERSION\",\n  \"domain\": \"$cfg_domain\",\n  \"trustedHost\": \"$trusted\",\n  \"publicIp\": \"$PUBLIC_IP\",\n  \"gatePort\": $GATE_PORT,\n  \"dshPort\": $DSH_PORT,\n  \"mirror\": \"${MIRROR:-default}\",\n  \"installedAt\": \"$(date -u +%Y-%m-%dT%H:%M:%SZ)\"\n}\nEOF\n\tchmod 600 \"$INSTALL_ROOT/state/config.json\"\n\tchown \"$DSH_USER\" \"$INSTALL_ROOT/state/config.json\"\n\tchown \"$DSH_USER\" \"$INSTALL_ROOT/state\" \"$INSTALL_ROOT/backups\"\n\tchmod 700 \"$INSTALL_ROOT/state\"\n\n\t# systemd unit（模板替换 node 路径）\n\tlocal node_bin\n\tnode_bin=$(command -v node)\n\tfetch_file units/dsh-gate.service /tmp/dsh-gate.service.tpl\n\tsed \"s|__NODE_BIN__|${node_bin}|\" /tmp/dsh-gate.service.tpl >/etc/systemd/system/dsh-gate.service\n\tsystemctl daemon-reload\n\tsystemctl enable dsh-gate >/dev/null 2>&1\n\tsystemctl restart dsh-gate\n\tlog \"dsh-gate.service 已启动（DSH_TRUSTED_HOST=${trusted}）\"\n\t# 浏览器一键升级：DSH 有新版本时页面提示，确认后由 root 服务执行升级\n\t\"$INSTALL_ROOT/bin/dsh-vps\" install-units || warn \"一键升级单元安装失败（不影响使用，可稍后 sudo dsh-vps install-units）\"\n}\n\n## endregion\n\n## region: 步骤 8：防火墙\n\nstep8_firewall() {\n\tlog \"步骤 8/9：防火墙\"\n\tif command -v ufw >/dev/null 2>&1; then\n\t\tufw allow 22/tcp >/dev/null\n\t\tufw allow 80/tcp >/dev/null\n\t\tufw allow 443/tcp >/dev/null\n\t\tlog \"ufw 已放行 22/80/443\"\n\telse\n\t\tlog \"未检测到 ufw，跳过（请自行确认云厂商安全组放行 80/443）\"\n\tfi\n}\n\n## endregion\n\n## region: 步骤 9：健康自检 + 完成输出\n\nwait_gate_health() {\n\tlocal i body\n\tfor i in $(seq 1 30); do\n\t\tbody=$(curl -fsS --max-time 3 \"http://127.0.0.1:$GATE_PORT/gate/health\" 2>/dev/null) || { sleep 2; continue; }\n\t\tif printf '%s' \"$body\" | grep -q '\"gate\":\"ok\"'; then\n\t\t\tprintf '%s' \"$body\"\n\t\t\treturn 0\n\t\tfi\n\t\tsleep 2\n\tdone\n\treturn 1\n}\n\nstep9_verify() {\n\tlog \"步骤 9/9：健康自检\"\n\tlocal body healthy=1\n\tbody=$(wait_gate_health) || {\n\t\twarn \"gate 未就绪，请查看: journalctl -u dsh-gate -n 50\"\n\t\tdie \"健康检查失败（gate）\"\n\t}\n\t# 等待 DSH 子进程启动 + launchToken 兑换完成（冷启动需要几秒到几十秒，小内存机器更久）\n\twait_dsh_session || healthy=0\n\t# 官方最新版起不来（网关记下了启动错误，而不只是慢）：退回已验证版本再等一轮，\n\t# 与页面一键升级失败自动回滚同一思路。只是冷启动慢就不退，免得白白装回旧版\n\tif [[ $healthy -eq 0 && \"$DSH_VERSION\" != \"$DSH_VERIFIED\" ]] \\\n\t\t&& printf '%s' \"$LAST_HEALTH\" | grep -q '\"lastError\":\"'; then\n\t\twarn \"DSH $DSH_VERSION 没能正常启动，退回已验证版本 $DSH_VERIFIED\"\n\t\tif install_dsh_version \"$DSH_VERIFIED\"; then\n\t\t\tDSH_VERSION=\"$DSH_VERIFIED\"\n\t\t\tDSH_PICKED_BY=\"已验证版本（最新版启动失败后退回）\"\n\t\t\tsed -i \"s/\\\"dshVersion\\\": *\\\"[^\\\"]*\\\"/\\\"dshVersion\\\": \\\"$DSH_VERSION\\\"/\" \"$INSTALL_ROOT/state/config.json\" || true\n\t\t\tln -sfn \"$DSH_VERSION\" \"$INSTALL_ROOT/dsh/current\"\n\t\t\tdsh-vps ownshost on >/dev/null 2>&1 || true\n\t\t\tsystemctl restart dsh-gate\n\t\t\thealthy=1\n\t\t\twait_dsh_session || healthy=0\n\t\tfi\n\tfi\n\t[[ $healthy -eq 1 ]] && log \"gate 正常，DSH 会话兑换成功\"\n\tfinish_summary \"$healthy\"\n}\n\n# 等 DSH 子进程启动并兑换会话；成功返回 0\nwait_dsh_session() {\n\tlocal i body\n\tfor i in $(seq 1 60); do\n\t\tbody=$(curl -fsS --max-time 3 \"http://127.0.0.1:$GATE_PORT/gate/health\" 2>/dev/null) || true\n\t\tLAST_HEALTH=\"$body\"\n\t\tif printf '%s' \"$body\" | grep -q '\"launchTokenCaptured\":true' \\\n\t\t\t&& printf '%s' \"$body\" | grep -q '\"dshCookie\":{\"authority\"'; then\n\t\t\treturn 0\n\t\tfi\n\t\tif [[ $i -eq 60 ]]; then\n\t\t\t# 不在这里退出：令牌链接只在最后打印，退出了用户就只剩\"缺少令牌\"页\n\t\t\twarn \"DSH 会话兑换超时（DSH 可能仍在启动，或启动失败）\"\n\t\t\tlocal err\n\t\t\terr=$(printf '%s' \"$body\" | sed -n 's/.*\"lastError\":\"\\([^\"]*\\)\".*/\\1/p')\n\t\t\t[[ -n \"$err\" ]] && warn \"最近错误: $err\"\n\t\t\twarn \"排查: journalctl -u dsh-gate -n 80 --no-pager\"\n\t\t\treturn 1\n\t\tfi\n\t\tsleep 2\n\tdone\n\treturn 1\n}\n\nfinish_summary() {\n\tlocal healthy=\"$1\"\n\n\tlocal url=\"https://$TRUSTED_HOST\"\n\tlocal open_url=\"$url\"\n\t[[ -n \"$SETUP_TOKEN\" ]] && open_url=\"$url/setup?token=$SETUP_TOKEN\"\n\n\techo\n\techo \"============================================================\"\n\tif [[ $healthy -eq 1 ]]; then\n\t\techo \" dsh-vps 安装完成\"\n\telse\n\t\techo \" dsh-vps 已安装，但 DSH 尚未就绪（见上方警告；页面会显示启动进度与错误）\"\n\tfi\n\techo \"------------------------------------------------------------\"\n\techo \" DSH 版本  : ${DSH_VERSION}（${DSH_PICKED_BY}）\"\n\techo \" 访问地址  : $open_url\"\n\tif [[ -n \"$SETUP_TOKEN\" ]]; then\n\t\techo \"             （初始设置需要上面的一次性令牌，别用不带令牌的地址）\"\n\telif [[ -z \"$DOMAIN\" ]]; then\n\t\techo \"             （未传 --domain，当前为自签证书过渡，浏览器会提示证书不受信任；域名可稍后在向导中填写）\"\n\tfi\n\techo \" 服务/日志 : systemctl status dsh-gate | journalctl -u dsh-gate -f\"\n\techo \" 管理命令  : dsh-vps status | restart | upgrade | rollback | reset-admin | setup-url | backup\"\n\techo \"------------------------------------------------------------\"\n\techo \" 下一步：\"\n\techo \" 1. 若使用域名，请先将 A 记录解析到本机（Caddy 会自动签发证书）\"\n\techo \" 2. 浏览器打开上面的访问地址，进入初始设置向导\"\n\techo \" 3. 填写管理员用户名/密码（+ 可选域名、DeepSeek API Key）→ 登录\"\n\tif [[ -n \"$SETUP_TOKEN\" ]]; then\n\t\techo\n\t\techo \" 令牌只此一份，链接丢了随时重取：sudo dsh-vps setup-url\"\n\tfi\n\techo \"============================================================\"\n}\n\n## endregion\n\nstep1_prechecks\nstep2_node\nstep3_dsh\nstep4_user\nstep5_gate\nresolve_trusted_host\nstep6_caddy\nstep7_systemd\nstep8_firewall\nstep9_verify\n"
    },
    {
      "path": "uninstall.sh",
      "content": "#!/usr/bin/env bash\n# dsh-vps 卸载脚本\n#\n# 用法：\n#   curl -fsSL https://raw.githubusercontent.com/AIcivilization/dsh-vps/main/uninstall.sh \\\n#     | sudo bash -s -- --yes\n#   # 或在仓库克隆目录内：\n#   sudo bash uninstall.sh [--yes] [--keep-data] [--purge-caddy]\n#\n# 目标 OS：Ubuntu 22.04+ / Debian 12+\n#\n# 顺序：备份 → 停服务 → 移除 unit 与安装目录 → 移除 Caddy 站点块 → 清 DSH 数据目录。\n# 任何一步失败都会就地停下（set -euo pipefail），不做半吊子清理。\n\nset -euo pipefail\n\n## region: 常量与参数\n\nINSTALL_ROOT=\"/opt/dsh-vps\"\nDSH_USER=\"dsh\"\nDSH_HOME_DIR=\"/home/dsh/.dsh\"\nSERVICE=\"dsh-gate\"\nUNIT_FILE=\"/etc/systemd/system/dsh-gate.service\"\nCADDY_SITE_FILE=\"/etc/caddy/dsh-site.conf\"\nCADDYFILE=\"/etc/caddy/Caddyfile\"\n\nASSUME_YES=0\nKEEP_DATA=0\nPURGE_CADDY=0\n\nlog()  { printf '\\033[1;32m[uninstall]\\033[0m %s\\n' \"$*\"; }\nwarn() { printf '\\033[1;33m[uninstall]\\033[0m %s\\n' \"$*\" >&2; }\ndie()  { printf '\\033[1;31m[uninstall]\\033[0m %s\\n' \"$*\" >&2; exit 1; }\n\nusage() {\n\tcat <<'EOF'\ndsh-vps 卸载脚本\n用法: sudo bash uninstall.sh [--yes] [--keep-data] [--purge-caddy]\n  --yes          跳过交互确认（脚本化调用时用）\n  --keep-data    保留 DSH 数据目录 /home/dsh/.dsh 与系统用户 dsh\n  --purge-caddy  连 Caddy 软件包与 apt 源一起移除（默认只删本产品的站点块）\nEOF\n}\n\nwhile [[ $# -gt 0 ]]; do\n\tcase \"$1\" in\n\t--yes) ASSUME_YES=1; shift ;;\n\t--keep-data) KEEP_DATA=1; shift ;;\n\t--purge-caddy) PURGE_CADDY=1; shift ;;\n\t-h | --help) usage; exit 0 ;;\n\t*) die \"未知参数: $1（--help 查看用法）\" ;;\n\tesac\ndone\n\n[[ $EUID -eq 0 ]] || die \"需要 root（sudo bash uninstall.sh ...）\"\n\n## endregion\n\n## region: 步骤 1：确认\n\nif [[ $ASSUME_YES -eq 0 ]]; then\n\tcat <<EOF\n即将移除 dsh-vps：\n  - 服务        ${SERVICE}（停止并禁用，删除 ${UNIT_FILE}）\n  - 安装目录    ${INSTALL_ROOT}（含 gate 代码、state、备份）\n  - 命令        /usr/local/bin/dsh-vps\n  - Caddy 站点  $CADDY_SITE_FILE$([ $PURGE_CADDY -eq 1 ] && echo \"（并移除 caddy 软件包）\")\n  - 隧道        /etc/wireguard/wg0.conf（仅当它是 dsh-vps vpn 创建的；你自己的 wg0 不动）\n  - DSH 数据    $DSH_HOME_DIR$([ $KEEP_DATA -eq 1 ] && echo \"（--keep-data：保留）\" || echo \"（删除）\")\n  - 系统用户    $DSH_USER$([ $KEEP_DATA -eq 1 ] && echo \"（--keep-data：保留）\" || echo \"（保留，重装可复用）\")\n\n删除前会先打包备份到 /root/dsh-vps-uninstall-<时间戳>.tar.gz\nEOF\n\tread -rp \"确认卸载？输入 yes 继续： \" ans\n\t[[ \"$ans\" == \"yes\" ]] || die \"已取消\"\nfi\n\n## endregion\n\n## region: 步骤 2：备份\n\nlog \"步骤 1/6：备份\"\nmkdir -p /root\nlocal_ts=\"dsh-vps-uninstall-$(date +%Y%m%d-%H%M%S).tar.gz\"\nBACKUP=\"/root/$local_ts\"\ntargets=()\n# 注意：set -e 下不能写 `[[ -d x ]] && arr+=(x)`——条件为假时整条列表返回非 0 会直接退出\nif [[ -d \"$INSTALL_ROOT/state\" ]]; then targets+=(\"${INSTALL_ROOT#/}/state\"); fi\nif [[ -d \"$INSTALL_ROOT/backups\" ]]; then targets+=(\"${INSTALL_ROOT#/}/backups\"); fi\nif [[ -d \"$DSH_HOME_DIR\" ]]; then targets+=(\"${DSH_HOME_DIR#/}\"); fi\n# Caddyfile 下一步会被改写，先连同站点块一起进备份\nif [[ -f \"$CADDYFILE\" ]]; then targets+=(\"${CADDYFILE#/}\"); fi\nif [[ -f \"$CADDY_SITE_FILE\" ]]; then targets+=(\"${CADDY_SITE_FILE#/}\"); fi\nif [[ ${#targets[@]} -gt 0 ]]; then\n\ttar -czf \"$BACKUP\" -C / \"${targets[@]}\" 2>/dev/null || warn \"部分文件无法打包（继续卸载）\"\n\tchmod 600 \"$BACKUP\"\n\tlog \"备份完成: $BACKUP\"\nelse\n\tBACKUP=\"\"\n\tlog \"没有可备份的内容\"\nfi\n\n## endregion\n\n## region: 步骤 3：停服务、移除 unit\n\nlog \"步骤 2/6：停止并移除 $SERVICE\"\nsystemctl stop \"$SERVICE\" 2>/dev/null || true\nsystemctl disable \"$SERVICE\" 2>/dev/null || true\nrm -f \"$UNIT_FILE\"\n# 浏览器一键升级单元\nsystemctl disable --now dsh-vps-upgrade.path 2>/dev/null || true\nrm -f /etc/systemd/system/dsh-vps-upgrade.path /etc/systemd/system/dsh-vps-upgrade.service\nsystemctl daemon-reload 2>/dev/null || true\nsystemctl reset-failed \"$SERVICE\" 2>/dev/null || true\n\n# gate 拉起的 DSH 子进程随 gate 停止而退出；残留则兜底清理\npkill -u \"$DSH_USER\" -f \"dsh/lib/bin.js\" 2>/dev/null || true\npkill -u \"$DSH_USER\" -f \"gate/server.js\" 2>/dev/null || true\n\n## endregion\n\n## region: 步骤 4：删文件\n\nlog \"步骤 3/6：移除安装目录与命令\"\nrm -rf \"$INSTALL_ROOT\"\nrm -f /usr/local/bin/dsh-vps\n\n## endregion\n\n## region: 步骤 5：Caddy\n\nlog \"步骤 4/6：移除 Caddy 站点块\"\nif [[ -f \"$CADDY_SITE_FILE\" ]]; then\n\trm -f \"$CADDY_SITE_FILE\"\nfi\nif [[ -f \"$CADDYFILE\" ]] && grep -qF \"import $CADDY_SITE_FILE\" \"$CADDYFILE\"; then\n\t# install.sh 覆盖前留下的原文件（Caddyfile.bak.<时间戳>）：取最新一份不含本产品 import 的还原；\n\t# 没有则换成占位文件，避免 Caddy 因 import 缺失而启动失败。\n\torig=\"\"\n\tfor f in $(ls -1t \"$CADDYFILE\".bak.* 2>/dev/null); do\n\t\tif ! grep -qF \"import $CADDY_SITE_FILE\" \"$f\"; then orig=\"$f\"; break; fi\n\tdone\n\tif [[ -n \"$orig\" ]]; then\n\t\tcp \"$orig\" \"$CADDYFILE\" && log \"已还原安装前的 Caddyfile（来自 $orig）\" \\\n\t\t\t|| warn \"Caddyfile 还原失败，请手工检查 $CADDYFILE\"\n\telse\n\t\tprintf '# Caddyfile 已被 dsh-vps 卸载脚本重置（原内容已备份进 %s）\\n' \"${BACKUP:-（无备份）}\" >\"$CADDYFILE\" \\\n\t\t\t|| warn \"Caddyfile 重置失败，请手工检查 $CADDYFILE\"\n\tfi\nfi\nif command -v caddy >/dev/null 2>&1; then\n\tsystemctl reload caddy 2>/dev/null || systemctl restart caddy 2>/dev/null || true\nfi\nif [[ $PURGE_CADDY -eq 1 ]]; then\n\tsystemctl stop caddy 2>/dev/null || true\n\tsystemctl disable caddy 2>/dev/null || true\n\tapt-get purge -y caddy >/dev/null 2>&1 || warn \"caddy 卸载失败（可能不是 apt 安装的）\"\n\trm -f /etc/apt/sources.list.d/caddy-stable.list /usr/share/keyrings/caddy-stable-archive-keyring.gpg\n\tlog \"已移除 caddy\"\nfi\n\n## endregion\n\n## region: 步骤 5：隧道\n\nlog \"步骤 5/6：移除隧道\"\nif [[ -f /etc/wireguard/wg0.conf ]] && ! grep -q \"dsh-vps\" /etc/wireguard/wg0.conf; then\n\tlog \"wg0.conf 不是 dsh-vps 创建的，保留不动\"\nelif [[ -f /etc/wireguard/wg0.conf ]]; then\n\tsystemctl stop wg-quick@wg0 2>/dev/null || true\n\tsystemctl disable wg-quick@wg0 2>/dev/null || true\n\trm -f /etc/wireguard/wg0.conf\n\tlog \"已移除 wg0（设备里的客户端配置请自行删掉）\"\nelse\n\tlog \"没有隧道，跳过\"\nfi\n\n## endregion\n\n## region: 步骤 6：DSH 数据\n\nlog \"步骤 6/6：处理 DSH 数据目录\"\nif [[ $KEEP_DATA -eq 1 ]]; then\n\tlog \"保留 ${DSH_HOME_DIR}（--keep-data）\"\nelse\n\trm -rf \"$DSH_HOME_DIR\"\n\tlog \"已删除 $DSH_HOME_DIR\"\nfi\n\n## endregion\n\ncat <<EOF\n\n卸载完成。\n  备份：${BACKUP:-（无）}\n重装：\n  curl -fsSL https://raw.githubusercontent.com/AIcivilization/dsh-vps/main/install.sh | sudo bash -s -- --domain <你的域名> --mirror cn\nEOF\n"
    },
